} function loadTTSFile(){ ttsButtonStatus("loading"); if($("#tts_file").val()=="" || $("#tts_file").val()=="undefined"){ $.ajax({ type: "GET", url: "/news/getTTSAjax.php?articleId="+articleId, dataType: "jsonp", success:function(result){ var tmpFile=result.content; $("#tts_file").val(tmpFile); //alert(tmpFile + " 로딩완료"); playTTS(); }, timeout: 1000*120, error:function(){ alert("데이터 수신에 실패 하였습니다."); } }); }else{ playTTS(); } } “상습적인 ‘남의 공 가로채기’, 민주당 후보들의 파렴치한 ‘숟가락 얹기’ 당장 중단하라”서울시의회 국민의힘이 최근 더불어민주당 서울시장 경선 토론회에서 벌어진 ‘성수역 3-1출입구 신설’과 관련해 다음과 같은 논평을 냈다.다음은 서울시의회 국민의힘 채수지 대변인 논평 전문최근 더불어민주당 서울시장 경선 토론회에서 벌어진 ‘성수역 3-1번 출입구 신설’ 공로 다툼은 서울 시민을 기만하는 대국민 사기극이자 볼썽사나운 촌극이다. 정원오 전 성동구청장과 전현희 국회의원이 남이 다 차려놓은 밥상을 두고 서로 자신의 공이라며 물어뜯는 모습은 최소한의 양심마저 내팽개친 뻔뻔함의 극치다.특히 전 의원의 상습적인 ‘공 가로채기’는 이미 도를 넘어섰다. 과거에도 단순 업무보고를 받은 것을 두고 본인이 출입구 신설을 주도한 양 허위 포장해 지탄받더니, 이번 경선에서도 똑같은 꼼수를 반복하고 있다. 타인의 피땀 어린 의정활동 성과를 자신의 치적으로 둔갑시키는 ‘정치적 도둑질’에 참담함을 금할 수 없다.성수역 출입구 신설은 국민의힘 소속 황철규 시의원이 3년여간 주도해 온 집념의 결과물이다. 황 의원은 2023년 1억원, 2024년 1억원 두 차례에 걸쳐 타당성 조사 예산을 직접 확보했고, 경제성을 이유로 사업이 무산될 위기 속에서도 시민 안전을 앞세워 끈질기게 관계 부서를 설득했다. 그 결과 19억원 규모의 사업비와 2025년 말 착공이라는 구체적인 추진 일정을 확정 지은 것이다.사정이 이렇듯 추진 경과와 기여 주체가 명백함에도 민주당 서울시장 후보들은 권력욕에 눈이 멀어 남의 것을 ‘내 것’이라며 서로 머리채 잡고 악다구니를 하고 있다. 시민의 안전과 직결된 지역 현안조차 자신들의 표 벌이를 위한 전리품으로 여기는 이들에게 어찌 서울 시민의 삶을 맡길 수 있겠는가. 민주당 서울시장 후보들은 시민의 눈을 속이려는 파렴치한 숟가락 얹기를 즉각 중단하고, 얄팍한 성과 탈취극으로 서울 시민을 우롱한 것을 무릎 꿇어 사과하라.남의 노력이나 훔쳐 시장직을 탐하는 정 전 구청장과 전 의원의 비열한 구태 정치는 반드시 천만 서울 시민의 준엄한 철퇴를 맞을 것이다. 알맹이 없는 거짓 선동으로 표 훔칠 생각 말고, 진정 시민의 삶을 위한 정책이 무엇인지 깊이 고민하길 바란다.2026년 3월 23일 서울시의회 국민의힘 대변인 채수지온라인뉴스부 Copyright ⓒ 서울신문 All rights reserved. 무단 전재-재배포, AI 학습 및 활용 금지 지방자치 최신 기사 고양 꽃박람회, 시간을 물들이다 울산 반구천 암각화, 하루 8회 버스 다녀요 봄날은 갔다… 냉해 맞은 과수원 어린이날 ‘서울형 키즈카페’ 60곳 무료 개방 봄날은 왔다… 신품종 심는 농가 곡우 넘긴 보성, 명품 찻잎 본격 출하 제주 ‘탄소 저장고’ 순비기 군락 조성 “한예종, 예향의 도시에 유치”…광주 국회의원 8명 서울 ‘땅꺼짐 촉매’ 노후 상수도관 343㎞ 교체한 ‘수질오염과의 전쟁’ 충북, 3대 유역 개선 window._taboola = window._taboola || []; _taboola.push({ mode: 'thumbnails-a', container: 'taboola-below-article-thumbnails