mg.seoul.co.kr/img/12_lightbox-ico-loading.gif', imageBlank: '//img.seoul.co.kr/img/12_lightbox-blank.gif', imageBtnPrev: '//img.seoul.co.kr/img/12_pre_i.gif', imageBtnNext: '//img.seoul.co.kr/img/12_next_i.gif', imageBtnClose: '//img.seoul.co.kr/img/12_close_i.gif', overlayOpacity:0.6 } ); }); 토크콘서트 중인 서준오 의원 서 의원의 저서 ‘미래로 가는 노원’은 희망촌에서 성장한 한 청년이 도시정책 전문가이자 서울시의원으로 성장하기까지의 과정을 그린 동시에, 창동차량기지 S-DBC 조성, 광운대역세권 개발, 한전 인재개발원 부지 활용 등 노원 3대 일자리 벨트 구축 전략을 중심으로 ‘미래 노원 시즌3’의 청사진을 제시한 책이다. 또한 ‘도시는 건물이 아닌 사람의 꿈’이라는 저자의 도시철학과 “나의 자리에 당신을 놓겠습니다”라는 정치철학을 담아 노원을 베드타운에서 미래 경제도시로 전환시키겠다는 비전을 강조하고 있다. $(window).load(function() { jQuery('#gallery1783241 a').lightBox({ imageLoading: '//img.seoul.co.kr/img/12_lightbox-ico-loading.gif', imageBlank: '//img.seoul.co.kr/img/12_lightbox-blank.gif', imageBtnPrev: '//img.seoul.co.kr/img/12_pre_i.gif', imageBtnNext: '//img.seoul.co.kr/img/12_next_i.gif', imageBtnClose: '//img.seoul.co.kr/img/12_close_i.gif', overlayOpacity:0.6 } ); }); 노원구민의전당을 가득 채운 참석자들 서 의원은 행사에서 “3000명이 넘는 주민 여러분께서 한마음으로 축하해주셔서 깊은 감동을 받았다”며 “도시와 사람을 연결하는 정치, 시민의 꿈을 설계하는 정치가 무엇인지 다시 한번 마음에 새겼다”고 소감을 밝혔다. 이어 “주신 성원은 제게 더 큰 책임”이라며 “미래 노원을 만드는 여정을 결코 멈추지 않고, 항상 겸손한 자세로 노원구민과 함께 나아가겠다”고 다짐했다.한편, 서 의원은 그동안 백사마을 재개발, 상계뉴타운·월계동 모아타운 사업, 경춘선숲길 활성화, 공공임대주택 개선, 창동차량기지 S-DBC 밑그림 설계 등 노원의 주요 도시발전 과제를 선도하며 실질적 성과를 만들어왔다. 이번 출판기념회는 이러한 성과에 대해 주민들이 보내는 신뢰와 기대가 결집된 자리로 평가된다.서 의원은 “노원의 미래는 이미 시작됐다”며 “앞으로도 노원구민의 꿈이 도시의 미래가 되는 노원을 만들기 위해 흔들림 없이 뛰겠다”고 밝혔다.온라인뉴스팀 Copyright ⓒ 서울신문 All rights reserved. 무단 전재-재배포, AI 학습 및 활용 금지 지방자치 최신 기사 고양 꽃박람회, 시간을 물들이다 울산 반구천 암각화, 하루 8회 버스 다녀요 봄날은 갔다… 냉해 맞은 과수원 어린이날 ‘서울형 키즈카페’ 60곳 무료 개방 봄날은 왔다… 신품종 심는 농가 곡우 넘긴 보성, 명품 찻잎 본격 출하 제주 ‘탄소 저장고’ 순비기 군락 조성 “한예종, 예향의 도시에 유치”…광주 국회의원 8명 서울 ‘땅꺼짐 촉매’ 노후 상수도관 343㎞ 교체한 ‘수질오염과의 전쟁’ 충북, 3대 유역 개선 window._taboola = window._taboola || []; _taboola.push({ mode: 't

