은 청각장애인들이 주축이 되어 구두를 제작하는 곳으로 과거 문재인 전 대통령의 낡은 구두로 화제가 됐던 기업이다. 정원오 서울시장 후보와 유보화 성동구청장 후보, 정청래 대표, 유시민 작가 등이 성수동 '아지오 성수점' 오픈 세레모니에서 기념 촬영하고 있다. 유 후보도 행사에 함께 참석해 수제화 산업과 사회적 기업의 결합이 지역 특색을 살리는 중요한 역할을 한다는 점이 강조하며 '아지오'의 사회적 의미를 널리 알리기 위한 노력을 이어가겠다는 의지를 밝혔다. 아지오 오픈식 이후, 유 후보는 정원오 후보와 함께 금남시장과 금호23재개발 구역을 차례로 찾아 본격적인 소통 행보에 나섰다. 먼저 금남시장을 방문한 두 후보는 상인 및 주민들과 지역 경제 활성화 방안에 대해 의견을 교환했다. 이어 금호23구역에서는 재개발 추진 상황을 점검하며 주민들의 고충을 직접 들었다. 금호23구역은 최근 신속통합기획 재개발사업 후보지로 입안 요청된 지역으로, 유 후보는 서울시의 적극적인 검토를 건의했다. 특히 이 자리에서 유 후보는 성동구의 미래를 위한 5대 핵심 건의사항을 정원오 후보에게 전달하기도 했다. 주요 내용은 ▲동북선 경전철 금호역 연장 ▲금호23구역 재개발 신속 추진 ▲체비지 내 노후 공공시설 신·개축 허용(도서관, 체육시설 등 노후 시설 현대화를 위한 서울시 조례 개정 건의) ▲시설물 관리 권한 자치구 이양(한강 둔치, 서울숲, 주요 간선도로 등의 관리 권한) ▲삼표부지 공공기여를 통한 컬처허브 조성 등이다. 유보화 성동구청장 후보는 "성동구는 급격한 변화의 중심에 있지만 여전히 교통과 주거환경에서 해결해야 할 숙제가 많다"며 "서울시와 긴밀히 협력해 성동구민의 삶의 질을 획기적으로 높이겠다"고 강조했다. 한편 이에 대해 정원오 후보는 "전달 받은 건의 사항들을 면밀히 검토해 성동구가 서울의 핵심 거점으로 고르게 발전할 수 있도록 적극 지원하겠다"고 말했다. $(function() { const copyUrlOptions=document.querySelectorAll(".urlBtns, .sns_clipboard"); // 주소복사 이벤트 (v11-fl-v2 수정) copyUrlOptions.forEach(selector=>{ selector.addEventListener("click", (e)=>{ const target=e.target, targetBtn=target.closest("[data-clipboard-text]"); if (targetBtn===null) return; const url=targetBtn.getAttribute("data-clipboard-text")||""; Util.copyToClipboardToast(selector, '', url); }); }); // 사진 lightBox 이벤트 if (typeof ImageViewer != "undefined") { new ImageViewer(".photo-layout", 0); } }); 저작권자 © 한강타임즈 무단전재 및 재배포, AI학습 및 활용 금지 윤종철 기자 todaynt@naver.com 정치/행정부 다른기사 보기 정원오·유보화, 금남시장 찾아 현안 현장소통... 5대 건의사항 전달
