} function loadTTSFile(){ ttsButtonStatus("loading"); if($("#tts_file").val()=="" || $("#tts_file").val()=="undefined"){ $.ajax({ type: "GET", url: "/news/getTTSAjax.php?articleId="+articleId, dataType: "jsonp", success:function(result){ var tmpFile=result.content; $("#tts_file").val(tmpFile); //alert(tmpFile + " 로딩완료"); playTTS(); }, timeout: 1000*120, error:function(){ alert("데이터 수신에 실패 하였습니다."); } }); }else{ playTTS(); } } 서울시의회 더불어민주당이 지난달 31일 ‘지방자치법 일부개정법률안’이 국회 본회의를 통과한 것과 관련해 입장문을 냈다.다음은 서울시의회 더불어민주당 박수빈 대변인 입장문 전문주민자치회의 설치와 운영, 행정적·재정적 지원 근거를 담은 ‘지방자치법 일부개정법률안’이 지난달 31일 국회 본회의를 통과했다. ‘지방자치분권 및 지역균형발전에 관한 특별법’에 의존한 시범 운영에 국한됐던 주민자치회는 13년 만에야 비로소 명확한 제도적 기반을 마련하게 됐다.서울시의회 더불어민주당(대표의원 성흠제, 은평1)은 이재명 정부의 자치분권 분야 핵심 국정 목표인 ‘주민주권 지방정부 구현’을 위한 마중물이자, 국민의힘 주도의 전 정부 아래에서 짓밟혀 왔던 주민자치 부활을 위한 신호탄으로서의 지방자치법 개정을 적극 환영한다.주민자치회는 주민 참여와 공동체의 숙의를 기반으로 지역의 정책 개발과 문제 해결을 주도해 왔다. 서울시의 경우 2017년 금천·도봉·성동·성북 등 4개 구 26개 동을 대상으로 시범 사업을 시작해 2021년에는 22개 구 261개 동으로 확대됐다. 2017년 당시 14억원에 불과했던 관련 예산은 2021년 202억원 수준으로 늘어났다.그러나 2021년 보궐선거에서 승리한 오세훈 시장은 취임과 함께 ‘비정상의 정상화’라는 악의적인 프레임으로 주민자치회에 대해 무리한 감사와 대대적인 예산 삭감을 자행했다. 그 과정에서 일부 주민자치회는 위축되거나 사라졌고, 수많은 주민자치 사업, 민관 협치 사업, 마을 공동체 사업들이 축소·폐기됐다. ‘자치’와 ‘협치’가 퇴보하고 ‘주민주권’이 실종된 자리에는 일방적 정책의 수혜자나 소비자로만 주민을 인지하는 무지한 관치 행정이 들어섰다.서울시의회 더불어민주당은 이번 지방자치법 개정을 계기로 그동안 오 시장과 국민의힘 주도로 일방적으로 축소·폐지된 주민자치 관련 조례와 사업들을 전면 재검토해 훼손되고 왜곡된 참여민주주의의 회복을 위해 모든 의정 역량을 기울일 것이다.정부는 참고 조례안을 준비하고, 지역 유형별 맞춤형 운영 모델을 개발·보급하며 권역별 컨설팅을 실시하는 등 주민자치 활성화를 위한 정책적 지원을 확대한다고 밝혔다.서울시의회 더불어민주당도 지역 맞춤형 의제를 발굴하고, 주민 참여 예산을 확대하며, 민·관 협치 사업을 적극 추진하는 등 주민 참여형 의사결정과 민원 해결을 위한 제도적·행정적 기반을 마련함으로써 정부와 발맞추어 주민주권 시대를 준비할 것이다.주민과 공동체는 정책의 능동적 설계자이자 결정 주체다. 서울시의회 더불어민주당은 ‘참여’에서 더 나아가 ‘권리와 권한’의 주민자치 실현을 위해 변함없이 노력할 것을 다짐한다.서울시의회 더불어민주당 대변인 박수빈온라인뉴스부 Copyright ⓒ 서울신문 All rights reserved. 무단 전재-재배포, AI 학습 및 활용 금지 지방자치 최신 기사 고양 꽃박람회, 시간을 물들이다 울산 반구천 암각화, 하루 8회 버스 다녀요 봄날은 갔다… 냉해 맞은 과수원 어린이날 ‘서울형 키즈카페’ 60곳 무료 개방 봄날은 왔다… 신품종 심는 농가 곡우 넘긴 보성, 명품 찻잎 본격 출하 제주 ‘탄소 저장고’ 순비기 군락 조성 “한예종, 예향의 도시에 유치”…광주 국회의원 8명 서울 ‘땅꺼